from pathlib import Path
p=Path('dist/experience.js');s=p.read_text(encoding='utf-8')
s=s.replace("node.querySelectorAll('.card-holder,.card-printed-number').forEach(el=>el.animate(opening?[{opacity:.75},{opacity:1}]:[{opacity:1},{opacity:.75}],{duration,easing:'ease-out',fill:'both'}));", """const number=node.querySelector('.card-printed-number'),sourceNumber=(opening?document.querySelector('.card-face[data-id=\"'+state.activeCard+'\"]'):to)?.querySelector('.card-printed-number');if(number){const full=number.querySelector('.card-number-full'),masked=number.querySelector('.card-number-masked');if(full&&masked){full.style.display=masked.style.display='inline';Object.assign(full.style,{position:'absolute',left:'0',top:'0'});full.animate(opening?[{opacity:0},{opacity:1}]:[{opacity:1},{opacity:0}],{duration,easing:'ease-out',fill:'both'});masked.animate(opening?[{opacity:1},{opacity:0}]:[{opacity:0},{opacity:1}],{duration,easing:'ease-out',fill:'both'})}const homeFont=(sourceNumber?parseFloat(getComputedStyle(sourceNumber).fontSize):17)/ratio,fullFont=parseFloat(getComputedStyle(number).fontSize);number.animate(opening?[{fontSize:homeFont+'px'},{fontSize:fullFont+'px'}]:[{fontSize:fullFont+'px'},{fontSize:homeFont+'px'}],{duration,easing:'cubic-bezier(.32,.72,0,1)',fill:'both'})}node.querySelector('.card-holder')?.animate(opening?[{opacity:0},{opacity:1}]:[{opacity:1},{opacity:0}],{duration,easing:'ease-out',fill:'both'});""")
p.write_text(s,encoding='utf-8')
p=Path('dist/interactions.js');s=p.read_text(encoding='utf-8').replace("icon('caret-down')", "icon('caret-right')")
s=s.replace("(dx<-75&&Math.abs(dx)>Math.abs(dy)*1.3)||(start.scroll===0&&dy<-90&&Math.abs(dy)>Math.abs(dx)*1.3)", "start.scroll===0&&dy>90&&Math.abs(dy)>Math.abs(dx)*1.3")
s=s.replace("{transform:'translate3d(-100%,0,0)'}],{duration:280", "{transform:'translate3d(0,100%,0)'}],{duration:280")
p.write_text(s,encoding='utf-8')
